window.kbPageData["views/entry/k-a325daf319f1a13b"] = {"key":"entry/k-a325daf319f1a13b","state":{"route":"entry/k-a325daf319f1a13b"},"node":{"id":"k-a325daf319f1a13b","mode":"k","title":"概念的交叉关系","type":"概念与词义","domain":"形式逻辑","reading":"","intro":"","priority":100,"aliases":["概念交叉关系的外延特征","概念交叉关系指外延有重合且各自有独有部分"],"qs":["国考 2023 行政执法 行测#91","江苏 2025 A类 行测#78"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":2,"repeatPositions":0,"directorySummary":"两个概念具有交叉关系，是指它们的外延有共同成员，同时各自都有对方外延之外的成员。","review":{"definition":"两个概念具有交叉关系，是指它们的外延有共同成员，同时各自都有对方外延之外的成员。","explanation":"本题中，木碗有的盛汤、有的作其他用途，汤碗也可以由木材或其他材质制成，因此B项的两个概念相互交叉。C项按题意是金簪属于发簪，属于种属关系。A、D也有外延交叉，选B还须匹配题干中材质在前、用途在后的顺序。","references":[],"evidence":"有的木碗是汤碗，有的木碗不是汤碗，有的汤碗是木碗，有的汤碗不是木碗，二者为交叉关系","disposition":"独立词条","basis":"据原题和解析编释。","title":"概念的交叉关系","related":[],"examFocus":{"国考 2023 行政执法 行测#91":"先判断两个概念的外延是否交叉，再比较每组词的命名依据和先后顺序。","江苏 2025 A类 行测#78":"找出每个概念的划分依据，再逐对检验是否既有共同成员，又各有独有成员。"}},"readings":[{"origin":"k-a325daf319f1a13b","title":"概念的交叉关系","qs":["国考 2023 行政执法 行测#91"],"definition":"两个概念具有交叉关系，是指它们的外延有共同成员，同时各自都有对方外延之外的成员。","explanation":"本题中，木碗有的盛汤、有的作其他用途，汤碗也可以由木材或其他材质制成，因此B项的两个概念相互交叉。C项按题意是金簪属于发簪，属于种属关系。A、D也有外延交叉，选B还须匹配题干中材质在前、用途在后的顺序。","evidence":"有的木碗是汤碗，有的木碗不是汤碗，有的汤碗是木碗，有的汤碗不是木碗，二者为交叉关系","doubt":"","references":[]},{"origin":"k-e11cc2b983ba00b0","title":"概念的交叉关系","qs":["江苏 2025 A类 行测#78"],"definition":"两个概念的外延有一部分重合，同时各自还有另一方未涵盖的对象，这两个概念就具有交叉关系。","explanation":"判断时要同时看共有部分和各自独有的部分。本土药材、野生药材、名贵药材分别按地域来源、生长方式和珍贵程度划分，两两之间都可能有重合，且各有独有的药材。A项的沿海高铁、跨省高铁、城际高铁分别从线路地理位置、是否跨省和服务对象来划分，同一条线路可以同时符合其中几项，因此与题干关系一致。","evidence":"三者互为交叉关系","doubt":"","references":[]}]},"questions":{"国考 2023 行政执法 行测#91":{"paper":"国考 2023 行政执法 行测","n":91,"mod":"判断推理","src":["857378cf496f27296500.pdf",19],"asrc":["d23139fe5a0fb3115135.pdf",29],"card":"c4c552402f5be828ed39bf6a","links":[{"id":"k-a325daf319f1a13b","role":"解题依据","why":"两个概念的外延有共同成员，也各自有独有成员，据此辨认交叉关系。"}]},"江苏 2025 A类 行测#78":{"paper":"江苏 2025 A类 行测","n":78,"mod":"判断推理","src":["98687766ac277f427cd6.pdf",15],"asrc":["4fe8e0544dd7b47699d2.pdf",25],"card":"c126ddf15c1903f6f461248d","links":[{"id":"k-a325daf319f1a13b","role":"直接考查","why":"所考查的外延关系取决于类别之间是否部分重合。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-a325daf319f1a13b":[["国考 2023 行政执法 行测#91"],["江苏 2025 A类 行测#78"]]}};
